mapper.select:
/* isry.itgcms.syscmmn.certimng.mapper.CertiMngMapper.selectCertiList */ SELECT CMMNS_CD_ID AS CMMNS_CD_ID , CMMNS_CD_VALUE AS CERTI_CD , CMMNS_CD_VALUE_NM AS CERTI_NM , ADDTNG_MNG_VALUE1 AS ENFC_INST_NM , ADDTNG_MNG_VALUE2 AS QLFC_ACQS_KND FROM SAC100 WHERE CMMNS_CD_ID = 'CERTI_LIST_SE_CD' AND ADDTNG_MNG_VALUE2 = #{QLFC_ACQS_KND}
AND CMMNS_CD_VALUE_NM LIKE '%' || #{CERTI_NM} || '%'
AND ADDTNG_MNG_VALUE1 LIKE '%' || #{ENFC_INST_NM} || '%'
ORDER BY CMMNS_CD_VALUE
